// requireSession 取当前 session；缺失直接 401。
func requireSession(ctx context.Context, c *app.RequestContext) (string, bool) {
	sess := middleware.SessionFromContext(ctx)
	if sess == nil {
		c.JSON(consts.StatusUnauthorized, map[string]string{"error": "missing session"})
		return "", false
	}
	return sess.Sub, true
}

// callbackURL 从请求拼 <origin>/api/mcp-oauth/callback。
func callbackURL(c *app.RequestContext) string {
	scheme := "http"
	if c.Request.URI().Scheme() != nil && string(c.Request.URI().Scheme()) == "https" {
		scheme = "https"
	}
	host := string(c.Request.Host())
	if host == "" {
		host = "localhost"
	}
	return scheme + "://" + host + "/api/mcp-oauth/callback"
}

// DiscoverOAuth POST /api/mcp-oauth/discover —— 探测 MCP server 是否需 OAuth。
func DiscoverOAuth(ctx context.Context, c *app.RequestContext) {
	if _, ok := requireSession(ctx, c); !ok {
		return
	}
	var req mcppb.DiscoverOAuthRequest
	if err := c.BindAndValidate(&req); err != nil {
		c.String(consts.StatusBadRequest, err.Error())
		return
	}
	res, err := McpOAuthSvc.DiscoverOAuth(ctx, req.GetUrl())
	if err != nil {
		// 不可达 → 502；其它 → 400。
		if err == mcpoauthservice.ErrURLRequired {
			c.JSON(consts.StatusBadRequest, map[string]string{"error": err.Error()})
			return
		}
		c.JSON(consts.StatusBadGateway, map[string]string{"error": err.Error()})
		return
	}
	c.JSON(consts.StatusOK, &mcppb.DiscoverOAuthResponse{
		OauthRequired: res.OAuthRequired,
		ServerOrigin:  res.ServerOrigin,
	})
}

// GetConnectionStatus GET /api/mcp-oauth/status —— 查连接状态（servers 逗号分隔）。
func GetConnectionStatus(ctx context.Context, c *app.RequestContext) {
	userID, ok := requireSession(ctx, c)
	if !ok {
		return
	}
	servers := string(c.Query("servers"))
	origins := strings.Split(servers, ",")
	statuses, err := McpOAuthSvc.GetConnectionStatus(ctx, userID, origins)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	out := make(map[string]*mcppb.ConnectionStatus, len(statuses))
	for origin, st := range statuses {
		out[origin] = &mcppb.ConnectionStatus{Connected: st.Connected, ExpiresAt: st.ExpiresAt}
	}
	c.JSON(consts.StatusOK, &mcppb.GetConnectionStatusResponse{Statuses: out})
}

// StartAuthorization GET /api/mcp-oauth/authorize —— 启动授权，302 redirect 到 MCP server authorize endpoint。
func StartAuthorization(ctx context.Context, c *app.RequestContext) {
	userID, ok := requireSession(ctx, c)
	if !ok {
		return
	}
	serverOrigin := string(c.Query("server_origin"))
	workspaceID := string(c.Query("workspace_id"))
	redirectURL, err := McpOAuthSvc.StartAuthorization(ctx, userID, serverOrigin, workspaceID, callbackURL(c))
	if err != nil {
		// control-plane 返回 errorPage HTML；此处简化为 HTML 错误页。
		c.Data(consts.StatusBadRequest, "text/html; charset=utf-8", []byte(mcpOAuthErrorHTML(err.Error())))
		return
	}
	c.Redirect(consts.StatusFound, []byte(redirectURL))
}

