// userIDFromCookie 从 cookie token 验证取 userID（callback 在 skip list，middleware 不注入 session）。
// 复用 middleware.VerifyToken（globalSigner 手动验签）。无 cookie/验签失败返回 ""——workflow 据此
// 判定 user 不匹配（pendingAuth.UserID != ""）→ 403。
func userIDFromCookie(ctx context.Context, c *app.RequestContext) string {
	tok := string(c.Cookie("token"))
	if tok == "" {
		return ""
	}
	sess, err := middleware.VerifyToken(tok)
	if err != nil {
		return ""
	}
	return sess.Sub
}

